def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    yesterday_bids = []
    dangerous_bids = []
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            yesterday_bids.append(float(bid))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                dangerous_bids.append(float(bid))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    highest_danger = max(dangerous_bids) if dangerous_bids else highest_prev

    alive_count = len(alive)
    contested = supply < WATER_REQ * 2
    very_tight = supply <= 18

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if contested:
        urgency += 1
    if very_tight:
        urgency += 1
    if alive_count >= 3:
        urgency += 1

    if urgency >= 5:
        target = max(92.0, highest_danger + 2.5)
    elif urgency >= 3:
        target = max(68.0, min(96.0, highest_prev + 1.5))
    else:
        if contested:
            target = max(42.0, min(72.0, highest_prev * 0.72))
        else:
            target = 24.0
            if highest_prev > 110:
                target = 19.0
            elif highest_prev > 80:
                target = 22.0

    if day >= 8 and hp > 4 and no_water_days == 0:
        target *= 0.9

    reserve = 0.0
    if day < 10:
        reserve = max(0.0, (10 - day) * 8.0)
    max_affordable = max(0.0, budget - reserve)
    if urgency >= 4:
        max_affordable = budget

    bid = min(target, max_affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, highest_danger + 3.0, 98.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Yesterday trace reaction
    prev_bids = []
    prev_hp = {}
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            bid = prev.get('bid', None)
            if bid is not None:
                prev_bids.append(float(bid))
            prev_hp[opp_id] = prev.get('hp_after', opp.get('hp', 0))
        else:
            prev_hp[opp_id] = opp.get('hp', 0)

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Supply pressure: medium scenario, supply between 15 and 25.
    # If supply is enough for 1 unit (>=9) but not huge, competition matters.
    # Scale target bid with supply magnitude.
    if supply < 18:
        supply_factor = 0.85
    elif supply < 22:
        supply_factor = 1.0
    else:
        supply_factor = 1.1

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # If opponents were bidding near/above salary, match just above their likely clearing price.
    # Use a small overbid to beat Cindy/Eric without going to maximum.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If we are healthy, be slightly conservative; if low hp, secure water.
        if my_hp > 5:
            target = (second_prev_bid + 3.0) * supply_factor
        else:
            target = (highest_prev_bid + 2.5) * supply_factor
    else:
        # Their bids were lower; we can bid around their top to ensure win.
        target = (highest_prev_bid + 1.5) * supply_factor

    # Convert target into a budget-safe cap based on our need to last across 10 days.
    # Conservative reserve: keep some budget for later if hp is OK.
    if my_hp > 5:
        budget_cap = my_budget * 0.35
    elif my_hp > 2:
        budget_cap = my_budget * 0.55
    else:
        budget_cap = my_budget * 0.85

    # Also cap by a fraction of daily salary to avoid overspending.
    max_reasonable = DAILY_SALARY * (0.95 if my_hp <= 2 else 0.75)

    bid = min(my_budget, budget_cap, max_reasonable, target)

    # Ensure non-negative and at least a minimal bid when we must compete.
    if bid < 0:
        bid = 0.0

    # If supply is very tight, increase slightly.
    if supply < 17 and my_hp <= 4:
        bid = min(my_budget, max(bid, DAILY_SALARY * 0.7))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        # If no alive opponents, bid minimally to save budget.
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If the highest bid yesterday was very aggressive
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If my HP is good, try to conserve budget
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # If my HP is low, bid aggressively to survive
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        # If the highest bid yesterday was not extremely aggressive, bid slightly above it
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If no yesterday's bids (e.g., first day or all opponents are new/no trace)
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    return min(my_status['budget'], DAILY_SALARY * 0.55)
